KeyGenerator kg = KeyGenerator.getInstance("AES");
kg.init(256, SecureRandom.getInstanceStrong());        // keys: platform RNG
SecretKey key = kg.generateKey();                      // or KeyStore.getKey(...)
Cipher c = Cipher.getInstance("AES/GCM/NoPadding");    // named, public algorithm
byte[] iv = new byte[12];
new SecureRandom().nextBytes(iv);                      // nonce: public, unique
c.init(Cipher.ENCRYPT_MODE, key, new GCMParameterSpec(128, iv));
